CREATE OR REPLACE PROCEDURE UnpivotProducts()
LANGUAGE plpgsql AS $$
DECLARE
    sql_query TEXT;
BEGIN
    SELECT STRING_AGG(
        'SELECT product_id, ''' || column_name || ''' AS store, ' || quote_ident(column_name) || ' AS price FROM Products WHERE ' || quote_ident(column_name) || ' IS NOT NULL',
        ' UNION ALL '
    )
    INTO sql_query
    FROM information_schema.columns
    WHERE table_name = 'products'
      AND column_name != 'product_id';
    EXECUTE sql_query;
END;
$$;

import pandas as pd

def unpivot_products(products: pd.DataFrame) -> pd.DataFrame:
    melted = products.melt(id_vars=['product_id'], var_name='store', value_name='price')
    return melted.dropna(subset=['price']).sort_values(['product_id', 'store'])
